const items = $input.all().map(item => item.json);
const batchId = $('Webhook Trigger (loan-notify)').first().json.body.batch_id;

// Read env configurations
const testEmailBase = $env.TEST_EMAIL_BASE || 'darshanpakhale06@gmail.com';
const maxEmails = parseInt($env.MAX_EMAILS_PER_RUN || '3', 10);
const isDryRun = ($env.EMAIL_DRY_RUN || 'false').toLowerCase() === 'true';

const atIdx = testEmailBase.indexOf('@');
const localPart = atIdx !== -1 ? testEmailBase.substring(0, atIdx) : 'darshanpakhale06';
const domainPart = atIdx !== -1 ? testEmailBase.substring(atIdx + 1) : 'gmail.com';

const words = ['one', 'two', 'three', 'four', 'five'];
const emailQueue = [];
const cappedItems = items.slice(0, maxEmails);

for (let i = 0; i < cappedItems.length; i++) {
  const user = cappedItems[i];
  const tag = words[i] || ('u' + (i + 1));
  const safeRecipient = `${localPart}+${tag}@${domainPart}`;
  const products = user.matched_products || [];

  let productListHtml = '';
  for (const prod of products) {
    const rate = prod.interest_rate_min ? `${prod.interest_rate_min}%` : 'Variable';
    const amt = prod.loan_amount_max ? `Up to ₹${Number(prod.loan_amount_max).toLocaleString('en-IN')}` : 'Flexible';
    productListHtml += `
      <li style="margin-bottom: 12px; padding: 12px; background: #f8fafc; border-radius: 6px; border: 1px solid #e2e8f0;">
        <strong style="color: #0f172a; font-size: 15px;">${prod.lender_name}</strong> – <span style="color: #334155;">${prod.product_name}</span><br/>
        <span style="font-size: 13px; color: #475569;">Interest Rate: <b>${rate}</b> | Max Loan Amount: <b>${amt}</b></span><br/>
        <a href="${prod.source_url}" style="color: #2563eb; font-size: 13px; text-decoration: none;">View Lender Product Details &rarr;</a>
      </li>`;
  }

  const htmlContent = `
    <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #1e293b; max-width: 600px; margin: 0 auto; padding: 24px; border: 1px solid #e2e8f0; border-radius: 8px;">
      <h2 style="color: #1e40af; margin-top: 0;">Loan Eligibility Engine – Product Matches</h2>
      <p style="font-size: 15px;">Hello <strong>${user.name || user.user_id}</strong>,</p>
      <p style="font-size: 14px; color: #334155;">Based on your applicant profile, here are the pre-qualified loan products matched for you:</p>
      <ul style="list-style: none; padding: 0;">
        ${productListHtml}
      </ul>
      <hr style="border: none; border-top: 1px solid #e2e8f0; margin: 24px 0;" />
      <p style="font-size: 12px; color: #94a3b8;">
        Dispatched to verified test inbox alias: <code>${safeRecipient}</code><br/>
        (Mapped from CSV user: ${user.csv_email})<br/>
        Demonstration pipeline operated via AWS SES &amp; n8n.
      </p>
    </div>
  `;

  const matchIds = products.map(p => p.match_id);

  emailQueue.push({
    batch_id: batchId,
    user_id: user.user_id,
    recipient_email: safeRecipient,
    subject: `Personal Loan Recommendations for ${user.name || user.user_id} (${safeRecipient})`,
    html_body: htmlContent,
    match_ids: matchIds,
    is_dry_run: isDryRun
  });
}

return emailQueue.map(e => ({ json: e }));

const item = $input.first().json;
return [{
  json: {
    ...item,
    delivery_status: 'simulated_sent',
    note: 'EMAIL_DRY_RUN is enabled. Email logged, not dispatched to SES.'
  }
}];
